-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere characters.sql, characters_full.sql y zzz_agentes.sql.
--
-- Materiales de ascension de los agentes de Zenless Zone Zero: lo que cuesta
-- cada subida de limite de nivel, del 10 al 60, con su icono, su cantidad y
-- los Deniques. Mismo formato que la columna ascension de Honkai.
--
-- Fuentes:
--   Nanoka (static.nanoka.cc) -> materiales, cantidades e iconos, sacados del
--     propio juego. Solo los trae en ingles.
--   Wiki de Zenless -> el nombre oficial en espanol de cada material
--     (plantilla "Other Languages" de su pagina).
--
-- Solo son updates: volver a ejecutarlo no duplica nada.
--
-- Generado el 2026-09-11. Se consiguieron para 60 de 60 personajes.

alter table public.characters add column if not exists ascension jsonb;

